(() => {
  // ===== CONFIG =====
  const PARENT_DT = "Item";                // parent doctype
  const SRC1 = "custom_enter_base_part_number"; // source field 1
  const SRC2 = "custom_select_quality";                 // source field 2
  const TARGET = "custom_mdb_part_number";      // target field
  const JOIN = "-";                             // delimiter

  // ===== HELPERS =====
  async function updateCombined(frm) {
    const src1 = (frm.doc[SRC1] || "").trim();
    const src2 = (frm.doc[SRC2] || "").trim();
    const parts = [src1, src2].filter(v => v !== "");
    const combined = parts.join(JOIN);

    await frm.set_value(TARGET, combined);
  }

  // ===== WIRING =====
  frappe.ui.form.on(PARENT_DT, {
    onload_post_render: updateCombined,
    refresh: updateCombined,
    validate: updateCombined,
    [SRC1]: updateCombined,  // run whenever SRC1 changes
    [SRC2]: updateCombined,  // run whenever SRC2 changes
  });
})();

frappe.ui.form.on("Item", {
  // Dynamic cleanup for custom_enter_base_part_number
  custom_enter_base_part_number: function(frm) {
    if (frm.doc.custom_enter_base_part_number) {
      const cleanVal = frm.doc.custom_enter_base_part_number.replace(/\s+/g, "");
      if (cleanVal !== frm.doc.custom_enter_base_part_number) {
        frm.set_value("custom_enter_base_part_number", cleanVal);
      }
    }
  },

  // Dynamic cleanup for custom_link_part_number_save
  custom_link_part_number_save: function(frm) {
    if (frm.doc.custom_link_part_number_save) {
      const cleanVal = frm.doc.custom_link_part_number_save.replace(/\s+/g, "");
      if (cleanVal !== frm.doc.custom_link_part_number_save) {
        frm.set_value("custom_link_part_number_save", cleanVal);
      }
    }
  },

  // Sync item_code with custom_mdb_part_number
  custom_mdb_part_number: function(frm) {
    if (frm.doc.custom_mdb_part_number) {
      frm.set_value("item_code", frm.doc.custom_mdb_part_number);
    }
  },

  // Final cleanup before save
  validate: function(frm) {
    if (frm.doc.custom_enter_base_part_number) {
      frm.set_value(
        "custom_enter_base_part_number",
        frm.doc.custom_enter_base_part_number.replace(/\s+/g, "")
      );
    }

    if (frm.doc.custom_link_part_number_save) {
      frm.set_value(
        "custom_link_part_number_save",
        frm.doc.custom_link_part_number_save.replace(/\s+/g, "")
      );
    }

    if (frm.doc.custom_mdb_part_number) {
      frm.set_value("item_code", frm.doc.custom_mdb_part_number);
    }
  }
});

