frappe.ui.form.on("Item Supplier", {
    supplier_part_no: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (frm.doc.item_code && row.supplier_part_no) {
            // Extract first letter + remaining
            let item_first = frm.doc.item_code.charAt(0);
            let item_rest = frm.doc.item_code.slice(1);

            let sup_first = row.supplier_part_no.charAt(0);
