frappe.ui.form.on('SRV BINNING', {
    onload(frm) {
        enforce_bin_button(frm);

        // 🔒 Patch Frappe's dirty state handler
        let original = frm.page.set_primary_action;
        frm.page.set_primary_action = function(label, action) {
            // Force BIN no matter what
            original.call(this, 'BIN', () => frm.save());
            // Also fix button text directly
            fix_dom_label(frm);
        };
    },

    refresh(frm) {
        enforce_bin_button(frm);
    }
});

function enforce_bin_button(frm) {
    frm.page.set_primary_action('BIN', () => frm.save());
    fix_dom_label(frm);
}

// 🔄 helper to directly rename button in DOM
function fix_dom_label(frm) {
    setTimeout(() => {
        let $btn = frm.page.btn_primary;
        if ($btn && $btn.length) {
            $btn.text('BIN');
        }
    }, 50);
}

