frappe.ui.form.on('PROJECT MASTER APPROVE', {
    refresh: function(frm) {

        // Set default workflow status for new records
        if (frm.is_new() && !frm.doc.work_flow_status) {
            frm.set_value('work_flow_status', 'Reject'); // Use a valid option
        }

        // Show buttons only if status = Active
        if (frm.doc.status === 'Active') {

            // --- Approve Button ---
            frm.add_custom_button(__('Approve'), function() {

                const save_and_approve = () => {
                    frm.set_value('work_flow_status', 'Approve');
                    frm.save().then(() => {
                        if (frm.doc.select_project) {
                            frappe.call({
                                method: 'frappe.client.set_value',
                                args: {
                                    doctype: 'PROJECT_MASTER',
                                    name: frm.doc.select_project,
                                    fieldname: 'work_flow_status',
                                    value: 'Approve'
                                },
                                callback: function() {
                                    frappe.msgprint(__('Approved! PROJECT_MASTER updated.'));
                                    frm.reload_doc();
                                }
                            });
                        }
                    });
                };

                // Save first if new, then approve
                if (frm.is_new()) {
                    frm.save().then(save_and_approve);
                } else {
                    save_and_approve();
                }
            }, __('Actions'));

            // --- Reject Button ---
            frm.add_custom_button(__('Reject'), function() {

                frappe.prompt([{
                    fieldname: 'remarks',
                    label: 'Remarks (mandatory)',
                    fieldtype: 'Small Text',
                    reqd: true
                }], function(values) {

                    const save_and_reject = () => {
                        frm.set_value('remarks', values.remarks);
                        frm.set_value('work_flow_status', 'Reject');
                        frm.save().then(() => {
                            if (frm.doc.select_project) {
                                frappe.call({
                                    method: 'frappe.client.set_value',
                                    args: {
                                        doctype: 'PROJECT_MASTER',
                                        name: frm.doc.select_project,
                                        fieldname: 'work_flow_status',
                                        value: 'Reject'
                                    },
                                    callback: function() {
                                        frappe.msgprint(__('Rejected with Remarks: {0}. PROJECT_MASTER updated.', [values.remarks]));
                                        frm.reload_doc();
                                    }
                                });
                            }
                        });
                    };

                    // Save first if new, then reject
                    if (frm.is_new()) {
                        frm.save().then(save_and_reject);
                    } else {
                        save_and_reject();
                    }

                }, __('Enter Remarks'), __('Reject'));
            }, __('Actions'));

        }

    }
});

