// Ref DocType: SRV_POST
//code to generate basic part no 
(() => {

  // ===== CONFIG =====

  const PARENT_DT = "SRV_POST";            // parent doctype

  const CHILD_DT = "SRV POST RE";          // child doctype

  const CHILD_TABLE_FIELD = "table_kyqc";  // fieldname of the Table on parent

  const SRC1 = "basic_part_no";  // child field 1

  const SRC2 = "quality";        // child field 2

  const TARGET = "mdb_part_no";  // child field to store combined value

  const JOIN = "-";              // delimiter

  // ===== HELPERS =====

  async function updateRowCombined(frm, cdt, cdn) {

    const row = locals[cdt][cdn] || {};

    const parts = [ row[SRC1],row[SRC2]]      // ORDER: quality - basic_part_no

      .map(v => (v == null ? "" : String(v).trim()))

      .filter(v => v !== "");

    const combined = parts.join(JOIN);

    await frappe.model.set_value(cdt, cdn, TARGET, combined);

  }

  async function recomputeAllRows(frm) {

    const rows = frm.doc[CHILD_TABLE_FIELD] || [];

    for (const r of rows) {

      await updateRowCombined(frm, CHILD_DT, r.name);

    }

    frm.refresh_field(CHILD_TABLE_FIELD);

  }

  // ===== WIRING =====

  // Parent events: keep values in sync when form loads/validates and when rows change

  const parentHandlers = {

    onload_post_render: recomputeAllRows,

    refresh: recomputeAllRows,

    validate: recomputeAllRows,

  };

  parentHandlers[`${CHILD_TABLE_FIELD}_add`] = recomputeAllRows;

  parentHandlers[`${CHILD_TABLE_FIELD}_remove`] = recomputeAllRows;

  frappe.ui.form.on(PARENT_DT, parentHandlers);

  // Child row events: recompute when either source field changes or the row renders

  const childHandlers = {};

  childHandlers[SRC1] = updateRowCombined;

  childHandlers[SRC2] = updateRowCombined;

  childHandlers.form_render = updateRowCombined;

  frappe.ui.form.on(CHILD_DT, childHandlers);

})();

