frappe.ui.form.on('PROJECT MASTER APPROVE', {
    refresh: function(frm) {
        if (frm.is_new()) {
            // ✅ Set default workflow status
            frm.set_value('work_flow_status', 'Pending for Approve');
            return;
        }

        // Show buttons only if status = Active
        if (frm.doc.status === 'Active') {

            // --- Approve Button ---
            frm.add_custom_button(__('Approve'), function() {
                frappe.prompt([{
                    fieldname: 'remarks',
                    label: 'Remarks (optional)',
                    fieldtype: 'Small Text',
                    reqd: false
                }],
                function(values) {
                    // Update current doc
                    frm.set_value('work_flow_status', 'Approve');
                    if (values.remarks) {
                        frm.set_value('remarks', values.remarks);
                    }

                    frm.save().then(() => {
                        // ✅ Update linked PROJECT-MASTER
                        if (frm.doc.projectmaster_link) {
                            frappe.call({
                                method: 'frappe.client.set_value',
                                args: {
                                    doctype: 'PROJECT-MASTER',
                                    name: frm.doc.projectmaster_link,
                                    fieldname: 'work_flow_status',
                                    value: 'Approve'
                                },
                                callback: function() {
                                    frappe.msgprint(__('Approved! PROJECT-MASTER updated.'));
                                    frm.reload_doc();
                                }
                            });
                        }
                    });
                },
                __('Enter Remarks (Optional)'),
                __('Approve'));
            }, __('Actions'));


            // --- Reject Button ---
            frm.add_custom_button(__('Reject'), function() {
                frappe.prompt([{
                    fieldname: 'remarks',
                    label: 'Remarks',
                    fieldtype: 'Small Text',
                    reqd: true
                }],
                function(values) {
                    // Update current doc
                    frm.set_value('remarks', values.remarks);
                    frm.set_value('work_flow_status', 'Reject');

                    frm.save().then(() => {
                        // ✅ Update linked PROJECT-MASTER
                        if (frm.doc.projectmaster_link) {
                            frappe.call({
                                method: 'frappe.client.set_value',
                                args: {
                                    doctype: 'PROJECT-MASTER',
                                    name: frm.doc.projectmaster_link,
                                    fieldname: 'work_flow_status',
                                    value: 'Reject'
                                },
                                callback: function() {
                                    frappe.msgprint(__('Rejected with Remarks: {0}. PROJECT-MASTER updated.', [values.remarks]));
                                    frm.reload_doc();
                                }
                            });
                        }
                    });
                },
                __('Enter Remarks'),
                __('Reject'));
            }, __('Actions'));
        }
    }
});

