// Client Script | Ref DocType: SRV_POST

frappe.ui.form.on("SRV_POST", {
  setup(frm)                { apply_active_filters_everywhere(frm); bind_screening_level_filter(frm); },
  onload(frm)               { apply_active_filters_everywhere(frm); bind_screening_level_filter(frm); },
  onload_post_render(frm)   { apply_active_filters_everywhere(frm); bind_screening_level_filter(frm); add_cancel_button(frm); enable_add_on_child_tables(frm); },
  refresh(frm)              { apply_active_filters_everywhere(frm); bind_screening_level_filter(frm); add_cancel_button(frm); enable_add_on_child_tables(frm); },

  async srv_no(frm) {
    // Guard: if user typed/pasted an inactive SRV ENTRY, clear it
    const name = frm.doc.srv_no;
    if (!name) return;

    try {
      const { message } = await frappe.call({
        method: "frappe.client.get_value",
        args: { doctype: "SRV ENTRY", fieldname: "status", filters: { name } }
      });
      const status = (message?.status || "").trim();
      if (status !== "Active") {
        await frm.set_value("srv_no", null);
        frappe.msgprint({
          title: "Not Allowed",
          message: "Please pick an Active SRV ENTRY.",
          indicator: "orange"
        });
        return;
      }
    } catch (e) {
      await frm.set_value("srv_no", null);
      return;
    }
  }
});

// ---- Helpers ----

// doctypes that must be filtered to status = Active (kept as-is)
const ACTIVE_DTYPES = new Set([
  "SRV ENTRY",      // existing: srv_no
  "STOCK_ID",       // card no
  "CARD_1C",        // child link
  "SCR_LEVEL",      // child link (update to your actual DocType name if different)
  "PROJECT_MASTER"  // child link
]);

function active_status_query() {
  return { filters: { status: "Active" } };
}

/**
 * Applies the "status = Active" filter to:
 * - Any parent-level Link field whose options matches ACTIVE_DTYPES
 * - Any Link field inside any child Table whose options matches ACTIVE_DTYPES
 */
function apply_active_filters_everywhere(frm) {
  if (!frm?.meta?.fields) return;

  // 1) Parent-level Link fields
  frm.meta.fields.forEach(df => {
    if (df.fieldtype === "Link" && ACTIVE_DTYPES.has(df.options)) {
      frm.set_query(df.fieldname, () => active_status_query());
    }
  });

  // 2) Child tables: walk each Table field and then its child docfields
  frm.meta.fields
    .filter(df => df.fieldtype === "Table")
    .forEach(tableDf => {
      const grid = frm.get_field(tableDf.fieldname)?.grid;
      if (!grid || !grid.docfields) return;

      grid.docfields.forEach(cdf => {
        if (cdf.fieldtype === "Link" && ACTIVE_DTYPES.has(cdf.options)) {
          const gf = grid.get_field(cdf.fieldname);
          if (gf) gf.get_query = () => active_status_query();
        }
      });
    });
}

/* ------------------------------------------------------------------
   EXTRA: Force the child column `screening_level` to show only Active.
   Works for inline grid rows and expanded row forms.
------------------------------------------------------------------- */
function bind_screening_level_filter(frm) {
  const CHILD_TABLE_FIELDNAME = "table_kyqc"; // change if your fieldname differs
  const grid = frm.fields_dict[CHILD_TABLE_FIELDNAME]?.grid;
  if (!grid) return;

  // Inline grid & link search dialog
  if (!grid.__screening_level_filter_bound__) {
    grid.__screening_level_filter_bound__ = true;

    frm.set_query("screening_level", CHILD_TABLE_FIELDNAME, () => ({
      filters: { status: "Active" }
    }));

    const gf = grid.get_field("screening_level");
    if (gf) gf.get_query = () => ({ filters: { status: "Active" } });
  }

  // Expanded row form
  if (!grid.__on_form_render_hook__) {
    grid.__on_form_render_hook__ = true;
    const prev = grid.on_form_render;
    grid.on_form_render = function (grid_row) {
      if (typeof prev === "function") prev(grid_row);
      const f = grid_row?.grid_form?.fields_dict?.screening_level;
      if (f && !f.__active_only__) {
        f.__active_only__ = true;
        f.get_query = () => ({ filters: { status: "Active" } });
      }
    };
  }
}

/* ------------------------------------------------------------------
   Add ONLY a red "Cancel" button
------------------------------------------------------------------- */
function add_cancel_button(frm) {
  if (frm.__cancel_btn_added) return; // avoid dupes
  frm.__cancel_btn_added = true;

  const btn = frm.add_custom_button(__('Cancel'), () => {
    frappe.confirm(
      __('Cancel and clear all fields? Unsaved data will be lost.'),
      () => frappe.new_doc(frm.doctype)
    );
  });

  $(btn).removeClass('btn-default btn-primary').addClass('btn-danger').css({ 'font-weight': 'bold' });
}

/* ------------------------------------------------------------------
   Ensure "Add Row" is enabled/visible on ALL child tables
   (useful if any earlier script hid it).
------------------------------------------------------------------- */
function enable_add_on_child_tables(frm) {
  (frm.meta.fields || [])
    .filter(df => df.fieldtype === 'Table')
    .forEach(df => enable_add_for_table(frm, df.fieldname));
}

function enable_add_for_table(frm, table_fieldname) {
  const field = frm.get_field(table_fieldname);
  const grid  = field && field.grid;
  if (!grid) return;

  // Allow adding rows
  frm.set_df_property(table_fieldname, 'cannot_add_rows', 0);
  grid.df.cannot_add_rows = false;
  grid.cannot_add_rows    = false;

  // Show footer add controls
  const $w = $(grid.wrapper);
  $w.find('.grid-add-row, .grid-add-multiple-rows, .grid-footer, .grid-footer-help').css('display','');

  // If any previous observer was hiding them, stop it
  if (grid.__hide_add_observer) { grid.__hide_add_observer.disconnect(); grid.__hide_add_observer = null; }

  // Apply immediately
  grid.refresh(false);
}

