// Client Script | Ref DocType: SRN BINNING
(() => {
  const LINK_TO_SOURCE = "srn_ref_no";     // Link -> SRN_POST
  const TARGET_CHILD   = "table_gfgm";     // child table on SRN BINNING

  const SOURCE_DT      = "SRN_POST";
  const SRC_CHILD_TABLE_FN = "table_agsm"; // child table field on SRN_POST

  // Parent field map (src_field -> target_field)
  const PARENT_MAP = {
    name:        "srn_ref_no",   // always store SRN_POST docname
    project:     "project",
    siv_no:      "siv_no",
    siv_date:    "siv_date",
    batch_no:    "batch_no",
    posted_from: "posted_from",
    screened_at: "screened_at"
  };

  // Child field map (src_field -> target_field)
  const CHILD_MAP = {
    mdb_part_no: "mdb_part_no",
    stock_name:  "stock_name",
    date_code:   "date_code",
    exp_date:    "exp_date",
    qty:         "qty",
    mfr_name:    "mfr_name",
    card_no:     "card_no",
    location:    "location",
    packet_no:   "packet_no"
  };

  // ---------- SOURCE RESOLVER ----------
  async function resolveSource(ref_val) {
    // 1. Direct docname match
    if (await frappe.db.exists(SOURCE_DT, ref_val)) {
      return ref_val;
    }

    // 2. Exact siv_no match
    let exact = await frappe.db.get_value(SOURCE_DT, { siv_no: ref_val }, "name");
    if (exact?.message?.name) return exact.message.name;

    // 3. Fuzzy matches
    let like = await frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: SOURCE_DT,
        filters: [
          ["siv_no", "like", `%${ref_val}%`],
          "or",
          ["name", "like", `%${ref_val}%`]
        ],
        fields: ["name", "siv_no"],
        limit: 10
      }
    });

    if (like.message?.length) {
      if (like.message.length === 1) {
        return like.message[0].name;
      }
      return new Promise(resolve => {
        let opts = like.message.map(r => `${r.name} (siv_no=${r.siv_no})`);
        frappe.prompt(
          [{ fieldtype: "Select", fieldname: "pick", label: "Select SRN_POST", options: opts }],
          (v) => {
            let chosen = v.pick.split(" ")[0];
            resolve(chosen);
          },
          "Multiple SRN_POST found",
          "Select"
        );
      });
    }

    return null;
  }

  // ---------- PULL FUNCTION ----------
  async function pullFromSource(frm) {
    if (frm.__pulling) return;
    frm.__pulling = true;

    try {
      let ref_val = (frm.doc[LINK_TO_SOURCE] || "").toString().trim();
      if (!ref_val) return;

      let docname = await resolveSource(ref_val);

      if (!docname) {
        frappe.msgprint({
          title: "Pull Failed",
          message: `❌ No ${SOURCE_DT} found for reference <b>${frappe.utils.escape_html(ref_val)}</b>`,
          indicator: "red"
        });
        return;
      }

      // fetch source document
      const { message: src } = await frappe.call({
        method: "frappe.client.get",
        args: { doctype: SOURCE_DT, name: docname },
      });
      if (!src) return;

      // copy parent fields
      for (const [from, to] of Object.entries(PARENT_MAP)) {
        if (src[from] !== undefined) {
          frm.set_value(to, src[from]);
        }
      }

      // clear + copy child table
      frm.clear_table(TARGET_CHILD);
      const rows = src[SRC_CHILD_TABLE_FN] || [];

      if (!rows.length) {
        frappe.msgprint(`⚠ No child rows found in ${SOURCE_DT}.${SRC_CHILD_TABLE_FN}`);
      }

      rows.forEach(s => {
        let t = frm.add_child(TARGET_CHILD);
        for (const [from, to] of Object.entries(CHILD_MAP)) {
          t[to] = s[from] ?? null;
        }
      });

      frm.refresh_field(TARGET_CHILD);
      frappe.show_alert(`✅ Pulled ${rows.length} row(s) from ${SOURCE_DT}.`);
    } catch (e) {
      console.error("Pull error", e);
      frappe.msgprint({
        title: "Pull Failed",
        message: e?.message || "Could not read the source. Check permissions/fieldnames.",
        indicator: "red"
      });
    } finally {
      frm.__pulling = false;
    }
  }

  // ---------- EVENT HOOK ----------
  frappe.ui.form.on("SRN BINNING", {
    refresh(frm) {
      // Add Pull button explicitly
      //frm.add_custom_button("Pull from SRN_POST", () => pullFromSource(frm));
    },
    srn_ref_no(frm) {
      // auto pull on link field change
      if (frm.doc.srn_ref_no) pullFromSource(frm);
    }
  });
})();

