const CHILD_TABLE_FN = "table_gfgm"; // <-- change to your child table fieldname if different

function enforce_child_grid_defaults(frm) {

  const field = frm.get_field(CHILD_TABLE_FN);

  const grid  = field && field.grid;

  if (!grid) return;

  const $w = $(grid.wrapper);

  // 1) Disallow adding rows, allow deleting rows (standard ERPNext delete in row menu)

  grid.df.cannot_add_rows = true;

  grid.cannot_add_rows    = true;

  grid.df.cannot_delete_rows = false;

  grid.cannot_delete_rows    = false;

  // 2) Hide footer add controls (but DO NOT touch row delete)

  $w.find('.grid-add-row, .grid-add-multiple-rows, .grid-footer-help').hide();

  // 3) Remove any custom buttons/containers we might have added earlier

  $w.find('.btn-delete-selected-inline').remove();

  $w.find('.child-inline-actions').remove();

  // 4) Remove any CSS we (or other scripts) added that hid the row delete action

  try {

    $('style').each(function () {

      const t = (this.textContent || '').toLowerCase();

      if (

        t.includes('.row-actions') &&

        (t.includes('[data-action="delete"]') || t.includes('.delete-row') || t.includes('.remove-row'))

      ) {

        this.parentNode && this.parentNode.removeChild(this);

      }

    });

    // reset any global flags we may have set previously

    window.__hide_row_actions_css_applied = false;

  } catch (e) { /* ignore */ }

  // 5) If earlier observers were injected to re-add custom buttons, disconnect them

  if (grid.__inline_btn_observer) { grid.__inline_btn_observer.disconnect(); grid.__inline_btn_observer = null; }

  // 6) Keep Add buttons hidden after any re-render

  if (!grid.__hide_add_observer) {

    grid.__hide_add_observer = new MutationObserver(() => {

      $w.find('.grid-add-row, .grid-add-multiple-rows, .grid-footer-help').hide();

    });

    grid.__hide_add_observer.observe($w[0], { childList: true, subtree: true });

  }

  // 7) Refresh to apply flags immediately

  grid.refresh(true);

}

// Client Script (Type: Client) | Ref DocType: SRV ENTRY FORM
(() => {
  const CHILD_TABLE_FIELD = "table_vuja";
  const CHILD_DOCTYPE = "SRV ENT TABLE";
  const REQUIRED_FIELDS = ["srv_part_no","comp_type","rec_qty","odered_qty","ret_qty","u_cost"];

  // ---- helpers ----
  const getGrid = (frm) => frm.get_field(CHILD_TABLE_FIELD)?.grid;
  const rowsOf = (frm) => frm.doc[CHILD_TABLE_FIELD] || [];
  const isMissing = (v) => v === undefined || v === null || v === "" || (typeof v === "number" && isNaN(v));

  const rowIsComplete = (row) => REQUIRED_FIELDS.every(f => !isMissing(row[f]));

  const lastRowIsComplete = (frm) => {
    const rows = rowsOf(frm);
    if (rows.length === 0) return true;            // allow adding the very first row
    return rowIsComplete(rows[rows.length - 1]);   // only the last row gates "Add Row"
  };

  const firstIncompleteRowIndex = (frm) => {
    const rows = rowsOf(frm);
    for (let i = 0; i < rows.length; i++) {
      if (!rowIsComplete(rows[i])) return i;
    }
    return -1;
  };

  const focusFirstMissingInRow = (frm, row) => {
    const grid = getGrid(frm);
    if (!grid || !row) return;
    const gr = grid.grid_rows_by_docname?.[row.name];
    if (!gr) return;
    gr.toggle_view(true);
    for (const f of REQUIRED_FIELDS) {
      if (isMissing(row[f])) {
        const fld = gr.grid_form?.fields_dict?.[f];
        if (fld?.$input) {
          frappe.utils.scroll_to(fld.$wrapper);
          fld.$input.focus();
        }
        break;
      }
    }
  };

  const setAddEnabled = (frm, enabled) => {
    const grid = getGrid(frm);
    if (!grid) return;
    grid.cannot_add_rows = !enabled;
    grid.refresh();
  };

  const guardAddRow = (frm) => {
    if (!lastRowIsComplete(frm)) {
      const rows = rowsOf(frm);
      const last = rows[rows.length - 1];
      frappe.msgprint({
        title: "Complete the current row first",
        message: `Please fill All Fields in row <b>${rows.length}</b> before adding another.`,
        indicator: "orange"
      });
      focusFirstMissingInRow(frm, last);
      return false;
    }
    return true;
  };

  // ---- parent events ----
  frappe.ui.form.on("SRV ENTRY FORM", {
    refresh(frm) {
      setAddEnabled(frm, lastRowIsComplete(frm));

      const grid = getGrid(frm);
      if (!grid) return;

      // intercept add/duplicate so user can’t sneak in an empty row
      if (!grid.__seq_guard__) {
        grid.__seq_guard__ = true;

        const _add = grid.add_new_row;
        grid.add_new_row = function (...a) {
          if (!guardAddRow(frm)) return;
          return _add.apply(this, a);
        };

        const _dup = grid.duplicate_row;
        grid.duplicate_row = function (...a) {
          if (!guardAddRow(frm)) return;
          return _dup.apply(this, a);
        };
      }
    },

    // when rows are added/removed via the table field, these events fire
    [`${CHILD_TABLE_FIELD}_add`](frm) {
      setAddEnabled(frm, lastRowIsComplete(frm));
    },
    [`${CHILD_TABLE_FIELD}_remove`](frm) {
      setAddEnabled(frm, lastRowIsComplete(frm));
    },

    // final safety: block save if any row is incomplete
    validate(frm) {
      const i = firstIncompleteRowIndex(frm);
      if (i >= 0) {
        const rows = rowsOf(frm);
        focusFirstMissingInRow(frm, rows[i]);
        frappe.throw(`Row <b>${i + 1}</b> is incomplete. Please fill: <b>${REQUIRED_FIELDS.join(", ")}</b>.`);
      }
    }
  });

  // ---- child row events ----
  // When any required field changes on ANY row, re-check the last row gate.
  const childHandlers = {};
  for (const f of REQUIRED_FIELDS) {
    childHandlers[f] = function (frm, cdt, cdn) {
      setAddEnabled(frm, lastRowIsComplete(frm));
    };
  }

  frappe.ui.form.on(CHILD_DOCTYPE, {
    ...childHandlers,
    form_render(frm) {
      setAddEnabled(frm, lastRowIsComplete(frm));
    }
  });
})();

// Client Script | Ref DocType: SRV ENTRY FORM
(() => {
  const DT = "SRV ENTRY FORM";
  const FIELD = "inward_no";   // 11-digit input
  const LAST5_FIELD = "srv_no"; // last 5 digits (Data field on SRV ENTRY FORM)

  // --- input guard: digits-only + max 11 while typing ---
  function bindInputGuard(frm) {
    const df = frm.get_field(FIELD);
    const $inp = df?.$input;
    if (!$inp || $inp.__bound_11digit) return;
    $inp.__bound_11digit = true;

    $inp.attr("maxlength", 11);

    $inp.on("input", () => {
      let v = $inp.val() || "";
      if (/\D/.test(v)) v = v.replace(/\D+/g, "");
      if (v.length > 11) {
        v = v.slice(0, 11);
        frappe.show_alert("Max 11 digits");
      }
      if (v !== $inp.val()) {
        $inp.val(v);
        frm.set_value(FIELD, v); // fine outside validate
      }
    });

    $inp.on("blur", () => {
      const v = $inp.val() || "";
      if (v && v.length < 11) {
        frappe.msgprint(`INWARD number must be exactly 11 digits.`);
      }
    });
  }

  const is11 = v => /^\d{11}$/.test(v || "");

  // write LAST5_FIELD synchronously (no await / no set_value)
  function syncLast5(frm) {
    const v = frm.doc[FIELD] || "";
    frm.doc[LAST5_FIELD] = v.length >= 5 ? v.slice(-5) : "";
    frm.refresh_field(LAST5_FIELD); // update UI if read-only
  }

  frappe.ui.form.on(DT, {
    onload_post_render(frm) {
      bindInputGuard(frm);
      syncLast5(frm);
    },
    refresh(frm) {
      bindInputGuard(frm);
      syncLast5(frm);
    },

    // keep clean while typing or other scripts set it
    [FIELD](frm) {
      const raw = frm.doc[FIELD] || "";
      const digits = raw.replace(/\D+/g, "").slice(0, 11);
      if (digits !== raw) {
        frm.doc[FIELD] = digits;      // sync write
        frm.refresh_field(FIELD);
      }
      syncLast5(frm);
    },

    // enforce before save (sync writes so payload includes the value)
    validate(frm) {
      if (!is11(frm.doc[FIELD])) {
        frappe.throw(`"${frappe.meta.get_label(DT, FIELD)}" must be exactly 11 digits.`);
      }
      syncLast5(frm);
    },

    before_save(frm) {
      syncLast5(frm); // final guarantee right before payload is posted
    }
  });
})();

