function hide_default_add_for_child(frm) {
  const CHILD_TABLE_FN = "table_kyqc";               // your child table fieldname
  const grid = frm.get_field(CHILD_TABLE_FN)?.grid;
  if (!grid) return;

  // 1) tell the grid it cannot add rows via default controls
  grid.df.cannot_add_rows = true;
  grid.cannot_add_rows    = true;

  // (we still allow delete via row actions)
  grid.df.cannot_delete_rows = false;
  grid.cannot_delete_rows    = false;

  // 2) hide footer add controls now
  const $w = $(grid.wrapper);
  const hide = () => {
    // bottom footer buttons + empty-state big button + footer help
    $w.find('.grid-add-row, .grid-add-multiple-rows, .grid-footer-help, .grid-empty').hide();
  };
  hide();

  // 3) keep them hidden after any grid refresh/rerender
  if (!grid.__hide_add_obs) {
    grid.__hide_add_obs = new MutationObserver(hide);
    grid.__hide_add_obs.observe($w[0], { childList: true, subtree: true });
  }

  // 4) apply immediately
  grid.refresh(false);
}

