function set_all_queries(frm) {
  // ===== Parent-level Link fields =====

  // S1 link (your field "srv_no" points to your S1/mirror doctype)
  // Show only Active and not-cancelled
  frm.set_query("srv_no", () => ({
    filters: { status: "Active", docstatus: ["!=", 2] },
    ignore_user_permissions: 0
  }));

  // Supplier (ERPNext core) -> uses "disabled" (not "status")
  frm.set_query("supplier", () => ({
    filters: { disabled: 0 },
    ignore_user_permissions: 0
  }));

  // Store (Warehouse) -> typically use disabled=0 and is_group=0 (only leaf warehouses)
  frm.set_query("store", () => ({
    filters: { disabled: 0, is_group: 0, docstatus: ["!=", 2] },
    ignore_user_permissions: 0
  }));

  // Project (ERPNext core) -> hide completed/cancelled
  frm.set_query("project", () => ({
    filters: { status: ["not in", ["Completed", "Cancelled"]], docstatus: ["!=", 2] },
    ignore_user_permissions: 0
  }));

  // ===== Child table Link fields =====
  const CHILD_TABLE = "table_child"; // your child table fieldname on SRV_POST

  // Put your child link fieldnames here. For any of these that point to core doctypes
  // like Supplier or Warehouse, set a dedicated filter below.
  const CHILD_LINKS_GENERIC_STATUS = ["type", "project", "card_no", "screening_level"];

  // Generic Active + not-cancelled filter (for custom doctypes that have a "status" field)
  CHILD_LINKS_GENERIC_STATUS.forEach((fieldname) => {
    frm.set_query(fieldname, CHILD_TABLE, () => ({
      filters: { status: "Active", docstatus: ["!=", 2] },
      ignore_user_permissions: 0
    }));
  });

  // EXAMPLES of special cases inside child rows (uncomment if you have such fields):
  //
  // Supplier inside child row (uses disabled)
  // frm.set_query("supplier", CHILD_TABLE, () => ({
  //   filters: { disabled: 0 },
  //   ignore_user_permissions: 0
  // }));
  //
  // Warehouse inside child row (leaf + enabled)
  // frm.set_query("warehouse", CHILD_TABLE, () => ({
  //   filters: { disabled: 0, is_group: 0, docstatus: ["!=", 2] },
  //   ignore_user_permissions: 0
  // }));
  //
  // Project inside child row (not completed/cancelled)
  // frm.set_query("project", CHILD_TABLE, () => ({
  //   filters: { status: ["not in", ["Completed", "Cancelled"]], docstatus: ["!=", 2] },
  //   ignore_user_permissions: 0
  // }));
}

// Client Script | Ref DocType: SRV_POST

(() => {

  const DT  = "SRV_POST";

  const LINK_TO_SOURCE = "srv_no";        // Link -> SRV ENTRY (docname)

  const TARGET_CHILD   = "table_kyqc";    // child table on SRV_POST

  const SOURCE_DT      = "SRV ENTRY";     // source parent

  const SRC_CHILD_TABLE_FN = "table_vuja";// child table fieldname on SRV ENTRY

  // Map SRV ENTRY -> SRV_POST (right side are SRV_POST fieldnames)

  const PARENT_MAP = {

    inward_no:      "inword_no",  // keep your exact target fieldname

    srv_date:       "srv_date",

    project:        "project",

    po_no:          "po_no",

    po_date:        "po_date",

    enter_supplier: "supplier",

    store:          "store",

  };

  // SRV ENT TABLE -> SRV_POST child row (right side are SRV_POST child fieldnames)

  const CHILD_MAP = {

    c_name:      "type",

    srv_part_no: "srv_part_no",

    rec_qty:     "recieved_quantity",

    // add more if needed: odered_qty, u_cost, ret_qty...

  };

  function targetFieldExists(frm, fn) { return !!frm.fields_dict[fn]; }

  // Require SRV ENTRY.status == "Active"

  async function ensureActiveSelection(frm) {

    const name = frm.doc[LINK_TO_SOURCE];

    if (!name) return false;

    const { message: m } = await frappe.call({

      method: "frappe.client.get_value",

      args: { doctype: SOURCE_DT, fieldname: "status", filters: { name } }

    });

    if (!m || m.status !== "Active") {

      await frm.set_value(LINK_TO_SOURCE, null);

      frappe.msgprint({ title: "Not Allowed", message: `Please select an <b>Active</b> ${SOURCE_DT}.`, indicator: "orange" });

      return false;

    }

    return true;

  }

  async function pullFromSource(frm) {

    if (frm.__pulling) return;

    frm.__pulling = true;

    try {

      const name = frm.doc[LINK_TO_SOURCE];

      if (!name) return;

      // verify and guard Active

      const ok = await ensureActiveSelection(frm);

      if (!ok) return;

      const exists = await frappe.db.exists(SOURCE_DT, name);

      if (!exists) {

        frappe.msgprint({

          title: "Pull Failed",

          message: `${SOURCE_DT} <b>${frappe.utils.escape_html(name)}</b> not found.<br><i>Nothing was cleared.</i>`,

          indicator: "orange"

        });

        return;

      }

      // load source (parent + children)

      const { message: src } = await frappe.call({

        method: "frappe.client.get",

        args: { doctype: SOURCE_DT, name }

      });

      // keep Link as the docname (don’t replace it with any field value)

      if (frm.doc[LINK_TO_SOURCE] !== name) await frm.set_value(LINK_TO_SOURCE, name);

      // copy parent fields

      for (const [from, to] of Object.entries(PARENT_MAP)) {

        if (targetFieldExists(frm, to) && src[from] !== undefined) {

          await frm.set_value(to, src[from]);

        }

      }

      // copy child rows (REPLACE only when we explicitly pull)

      frm.clear_table(TARGET_CHILD);

      const rows = src[SRC_CHILD_TABLE_FN] || [];

      for (const s of rows) {

        const t = frm.add_child(TARGET_CHILD);

        for (const [from, to] of Object.entries(CHILD_MAP)) {

          t[to] = s[from] ?? null;

        }

      }

      frm.refresh_field(TARGET_CHILD);

      // remember what we pulled (for diagnostics)

      frm.__last_pulled_source = name;

    } catch (e) {

      frappe.msgprint({

        title: "Pull Failed",

        message: e?.message || "Could not read the source. Check permissions and fieldnames.",

        indicator: "red"

      });

    } finally {

      frm.__pulling = false;

    }

  }

  // Only show Active SRV ENTRY in the picker

  function bindQueryOnce(frm) {

    if (frm.__bound_srv_no_query) return;

    frm.__bound_srv_no_query = true;

    frm.set_query(LINK_TO_SOURCE, () => ({ filters: { status: "Active" } }));

  }

  // Only auto-pull on initial creation when the grid is empty.

  function maybePullOnInitialLoad(frm) {

    const hasRows = (frm.doc[TARGET_CHILD] || []).length > 0;

    if (frm.is_new() && frm.doc[LINK_TO_SOURCE] && !hasRows) {

      pullFromSource(frm);

    }

  }

  frappe.ui.form.on(DT, {

    onload_post_render(frm) {

      bindQueryOnce(frm);

      // ⚠️ do NOT auto-pull on every load; only for brand-new docs with empty grid

      maybePullOnInitialLoad(frm);

    },

    refresh(frm) {

      bindQueryOnce(frm);

      // NO auto-pull here — prevents overwriting user edits after Save

    },

    // Pull ONLY when user changes srv_no

    async [LINK_TO_SOURCE](frm) {

      if (!frm.doc[LINK_TO_SOURCE]) {

        // cleared → don’t touch user data

        return;

      }

      // If child rows already exist, confirm before replacing them

    await pullFromSource(frm);

    },

  });

})();

// Client Script | Ref DocType: SRV BINNING
(() => {
  // ===== CONFIG: adjust to your exact fieldnames =====
  const DT                 = "SRV BINNING";
  const LINK_TO_POST       = "srv_no";         // Link (on BINNING) -> SRV_POST (docname)
  const SOURCE_POST_DT     = "SRV_POST";       // source parent DocType
  const SRC_CHILD_TABLE_FN = "table_kyqc";     // child table fieldname on SRV_POST
  const TARGET_CHILD_TABLE = "table_iuyx";     // child table fieldname on SRV BINNING

  // Parent mapping: LEFT = SRV_POST field, RIGHT = SRV BINNING field
  // NOTE: SRV_POST seems to store "inword_no" (typo) — map it into BINNING.inward_no
  const PARENT_MAP = {
    inword_no: "inward_no",
    srv_date:  "srv_date",
    project:   "project",
    po_no:     "po_no",
    po_date:   "po_date",
    supplier:  "supplier",
    store:     "store",
  };

  // Child row mapping: LEFT = SRV_POST child field, RIGHT = SRV BINNING child field
  // Packets/date code often differ by name between doctypes; both handled below.
  const CHILD_MAP = {
    manufacturer: "manufacturer",
    type:         "type",
    packet_no:    "pack_no",     // SRV_POST: packet_no  -> BINNING: pack_no
    mdb_part_no:  "mdb_part_no",
    card_no:      "card_no",
    location:     "location",
    // SRV_POST may have "date_code" or older "dc_code" — we handle both when copying
    date_code:    "dc_code",
    //FROM SRV ENT:SRV POST
    //dc_code:"date_code",
    expiry:       "expiry",
    stock:        "stock",
    posted_quantity:"posted_quantity"
    //need to set like this in another place of the code
    //project:"project"
    //project_name:"project_name",
    //project:      "project",
  };

  // ---------- helpers ----------
  function targetFieldExists(frm, fn) { return !!frm.fields_dict[fn]; }

  // Show ONLY Active SRV_POST in the srv_no picker.
  function bindActiveOnlyPicker(frm) {
    if (frm.__bound_active_srv_post) return;
    frm.__bound_active_srv_post = true;

    frm.set_query(LINK_TO_POST, () => ({
      filters: { status: "Active",srv_status: 0,docstatus: ["!=", 2] }   // parent filter ONLY (no child filters here)
    }));

    // (Optional) prevent creating new SRV_POST from the link field:
    // frm.set_df_property(LINK_TO_POST, "only_select", 1);
  }

  // If a user pastes an inactive SRV_POST docname, clear it and warn.
  async function guardActiveSelection(frm) {
    const name = frm.doc[LINK_TO_POST];
    if (!name) return true;

    try {
      const { message } = await frappe.call({
        method: "frappe.client.get_value",
        args: { doctype: SOURCE_POST_DT, fieldname: "status", filters: { name } }
      });
      if ((message?.status || "").trim() !== "Active") {
        await frm.set_value(LINK_TO_POST, null);
        frappe.msgprint({
          title: "Inactive SRV POST",
          message: `Please select an <b>Active</b> ${SOURCE_POST_DT}.`,
          indicator: "orange"
        });
        return false;
      }
    } catch {
      await frm.set_value(LINK_TO_POST, null);
      return false;
    }
    return true;
  }

  // Pull parent + ALL child rows from SRV_POST into SRV BINNING.
  async function pullFromPost(frm) {
    if (frm.__pulling_from_post) return;
    frm.__pulling_from_post = true;

    try {
      const name = frm.doc[LINK_TO_POST];
      if (!name) return;

      // Ensure it's active (UI lists only Actives, but protect against paste/typing).
      const ok = await guardActiveSelection(frm);
      if (!ok) return;

      // Load SRV_POST (includes its child table)
      const { message: src } = await frappe.call({
        method: "frappe.client.get",
        args: { doctype: SOURCE_POST_DT, name }
      });
      if (!src) {
        frappe.msgprint("Could not read SRV_POST (not found or no permission).");
        return;
      }

      // Keep Link as docname (do NOT set it to any label field)
      if (frm.doc[LINK_TO_POST] !== name) await frm.set_value(LINK_TO_POST, name);

      // --- copy parent fields (no duplicate fetch-from races) ---
      for (const [from, to] of Object.entries(PARENT_MAP)) {
        if (targetFieldExists(frm, to) && src[from] !== undefined) {
          await frm.set_value(to, src[from]);
        }
      }

      // --- copy ALL child rows (NO filtering on child doctypes) ---
      const rows = Array.isArray(src[SRC_CHILD_TABLE_FN]) ? src[SRC_CHILD_TABLE_FN] : [];
      frm.clear_table(TARGET_CHILD_TABLE);

      for (const s of rows) {
        const t = frm.add_child(TARGET_CHILD_TABLE);

        // Standard mapped fields
        t.manufacturer = s.manufacturer ?? null;
        t.type         = s.type ?? null;
        t.pack_no      = s.packet_no ?? null;               // packet_no -> pack_no
        t.mdb_part_no  = s.mdb_part_no ?? null;
        t.card_no      = s.card_no ?? null;
        t.location     = s.location ?? null;
        t.expiry       = s.expiry ?? null;
        t.stock        = s.stock ?? null;
        //t.project      = s.project ?? null;
        t.project_name=s.o_project_name??null;
        t.posted_quantity=s.posted_quantity??null;
        //t.project      = s.project ?? null;

        // Date code: accept either `date_code` or legacy `dc_code` from SRV_POST
        t.dc_code    = (s.date_code ?? s.dc_code) ?? null;
      }

      frm.refresh_field(TARGET_CHILD_TABLE);
      // Optional: toast
      // frappe.show_alert(`Copied ${rows.length} line(s) from ${SOURCE_POST_DT}.`);
    } catch (e) {
      frappe.msgprint({
        title: "Pull Failed",
        message: e?.message || "Could not read SRV_POST.",
        indicator: "red"
      });
      console.error(e);
    } finally {
      frm.__pulling_from_post = false;
    }
  }

  // ---------- hooks (do NOT auto-pull on every refresh to keep your edits) ----------
  frappe.ui.form.on(DT, {
    onload_post_render(frm) {
      bindActiveOnlyPicker(frm);
      // If opening an existing SRV BINNING that already has a link, you can auto-pull once:
      if (frm.is_new() && frm.doc[LINK_TO_POST]) pullFromPost(frm);
    },
    refresh(frm) {
      // Only re-bind the picker; DO NOT auto-pull on refresh (prevents overwriting user edits)
      bindActiveOnlyPicker(frm);
    },
    async [LINK_TO_POST](frm) {
      // If cleared, also clear the grid (leave other parent fields as-is by design)
      if (!frm.doc[LINK_TO_POST]) {
        frm.clear_table(TARGET_CHILD_TABLE);
        frm.refresh_field(TARGET_CHILD_TABLE);
        return;
      }
      // When the link changes, validate Active and then pull data
      (await guardActiveSelection(frm)) && pullFromPost(frm);
    }
  });

})();

// Numeric + alphabetic enforcement for SRV_POST → child "SRV POST RE"
(() => {
  const PARENT_DT      = "SRV_POST";
  const CHILD_ROW_DT   = "SRV POST RE";
  // If you know the table fieldname on SRV_POST, set it here (e.g. "table_kyqc").
  // If left null, we auto-detect the table that uses the child row doctype.
  const CHILD_TABLE_FN = null; // "table_kyqc";

  // ---- helpers ----
  const isEmpty = v => v == null || String(v).trim() === "";

  // allow "123", "123.45"
  function sanitizeNumber(val) {
    if (isEmpty(val)) return null;
    let s = String(val).trim().replace(/,/g, "");
    // keep only digits and a single dot
    s = s.replace(/[^0-9.]/g, "").replace(/^([^.]*\.)|\./g, "$1");
    if (!/^\d+(\.\d+)?$/.test(s)) return null;
    const n = parseFloat(s);
    return Number.isFinite(n) ? String(n) : null;
  }

  // allow letters + spaces only
  function sanitizeAlpha(val) {
    if (isEmpty(val)) return null;
    const before = String(val);
    const after  = before.replace(/[^A-Za-z\s]/g, "");
    return after.trim() === "" ? null : after;
  }

  function coerceChildRow(cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row) return;

    const origQty   = row.posted_quantity;
    const origMfr   = row.manufacturer;

    const num = sanitizeNumber(origQty);
    const txt = sanitizeAlpha(origMfr);

    row.posted_quantity = num;
    row.manufacturer    = txt;
  }

  // Try to add live input masks on the row form (optional UX sugar)
  function tryBindMasks(frm, cdt, cdn) {
    const tableField = resolveChildTableField(frm);
    const gridRow = frm.fields_dict[tableField]?.grid?.grid_rows_by_docname?.[cdn];
    const gf = gridRow?.grid_form;
    if (!gf) return;

    const qInp = gf.fields_dict.posted_quantity?.$input;
    const mInp = gf.fields_dict.manufacturer?.$input;

    if (qInp && !qInp.__mask_bound__) {
      qInp.__mask_bound__ = true;
      qInp.on("input", () => {
        const v = qInp.val();
        const filtered = v.replace(/[^0-9.]/g, "").replace(/^([^.]*\.)|\./g, "$1");
        if (filtered !== v) qInp.val(filtered);
      });
    }
    if (mInp && !mInp.__mask_bound__) {
      mInp.__mask_bound__ = true;
      mInp.on("input", () => {
        const v = mInp.val();
        const filtered = v.replace(/[^A-Za-z\s]/g, "");
        if (filtered !== v) mInp.val(filtered);
      });
    }
  }

  // Find the child table field on SRV_POST that uses "SRV POST RE"
  function resolveChildTableField(frm) {
    if (CHILD_TABLE_FN) return CHILD_TABLE_FN;
    for (const [fn, w] of Object.entries(frm.fields_dict)) {
      const df = w?.df;
      if (df?.fieldtype === "Table" && w.grid?.doctype === CHILD_ROW_DT) {
        return fn;
      }
    }
    // fallback: first table fieldname (worst case)
    for (const [fn, w] of Object.entries(frm.fields_dict)) {
      if (w?.df?.fieldtype === "Table") return fn;
    }
    return null;
  }

  // ---- bind child row events ----
  frappe.ui.form.on(CHILD_ROW_DT, {
    form_render(frm, cdt, cdn) {
      coerceChildRow(cdt, cdn);
      tryBindMasks(frm, cdt, cdn);
    },
    posted_quantity(frm, cdt, cdn) { coerceChildRow(cdt, cdn); },
    manufacturer(frm, cdt, cdn)    { coerceChildRow(cdt, cdn); }
  });

  // ---- parent hooks: coerce all rows before save ----
  frappe.ui.form.on(PARENT_DT, {
    validate(frm) {
      const tableField = resolveChildTableField(frm);
      const rows = tableField ? (frm.doc[tableField] || []) : [];
      rows.forEach(r => coerceChildRow(r.doctype, r.name));
      if (tableField) frm.refresh_field(tableField);
    },
    onload_post_render(frm) {
      // make sure masks try to attach for already-open row forms
      const tableField = resolveChildTableField(frm);
      const rows = tableField ? (frm.doc[tableField] || []) : [];
      rows.forEach(r => tryBindMasks(frm, r.doctype, r.name));
    }
  });
})();

// Numeric enforcement for SRV BINNING → its child table (qty only)
(() => {
  const PARENT_DT       = "SRV BINNING";
  // Set to your child Table fieldname, or leave null to auto-detect:
  const CHILD_TABLE_FN  = "table_iuyx"; // or null to auto-detect
  const CHILD_QTY_FIELD = "qty";        // fieldname on the child row
  const INTEGER_ONLY    = true;         // true = integers only, false = allow decimals

  // ---- helpers ----
  const isEmpty = v => v == null || String(v).trim() === "";

  function sanitizeQty(val) {
    if (isEmpty(val)) return null;
    let s = String(val).trim().replace(/,/g, "");

    if (INTEGER_ONLY) {
      s = s.replace(/[^\d]/g, "");                 // keep digits only
      return /^\d+$/.test(s) ? String(parseInt(s, 10)) : null;
    } else {
      s = s.replace(/[^0-9.]/g, "").replace(/^([^.]*\.)|\./g, "$1"); // keep one dot
      if (!/^\d+(\.\d+)?$/.test(s)) return null;
      const n = parseFloat(s);
      return Number.isFinite(n) ? String(n) : null;
    }
  }

  function resolveChildTableField(frm) {
    if (CHILD_TABLE_FN) return CHILD_TABLE_FN;
    for (const [fn, w] of Object.entries(frm.fields_dict)) {
      if (w?.df?.fieldtype === "Table") return fn;
    }
    return null;
  }

  function getChildDoctype(frm) {
    const tableFn = resolveChildTableField(frm);
    return frm.fields_dict[tableFn]?.grid?.doctype || null;
  }

  function coerceChildRow(cdt, cdn) {
    const row = locals[cdt]?.[cdn];
    if (!row) return;
    row[CHILD_QTY_FIELD] = sanitizeQty(row[CHILD_QTY_FIELD]);
  }

  // optional: live input mask in the row form
  function tryBindMask(frm, cdt, cdn) {
    const tableFn = resolveChildTableField(frm);
    const gridRow = frm.fields_dict[tableFn]?.grid?.grid_rows_by_docname?.[cdn];
    const gf = gridRow?.grid_form;
    if (!gf) return;
    const inp = gf.fields_dict[CHILD_QTY_FIELD]?.$input;
    if (!inp || inp.__mask_bound__) return;

    inp.__mask_bound__ = true;
    inp.on("input", () => {
      const v = inp.val();
      const filtered = INTEGER_ONLY
        ? v.replace(/[^\d]/g, "")
        : v.replace(/[^0-9.]/g, "").replace(/^([^.]*\.)|\./g, "$1");
      if (filtered !== v) inp.val(filtered);
    });
  }

  // Bind child handlers once we know the child doctype
  function ensureChildHandlers(frm) {
    const childDt = getChildDoctype(frm);
    if (!childDt) return;

    // prevent rebinding
    window.__srv_bin_child_bound = window.__srv_bin_child_bound || {};
    if (window.__srv_bin_child_bound[childDt]) return;
    window.__srv_bin_child_bound[childDt] = true;

    const handlers = {};
    handlers.form_render = function (frm, cdt, cdn) {
      coerceChildRow(cdt, cdn);
      tryBindMask(frm, cdt, cdn);
    };
    handlers[CHILD_QTY_FIELD] = function (frm, cdt, cdn) {
      coerceChildRow(cdt, cdn);
    };

    frappe.ui.form.on(childDt, handlers);
  }

  // Parent hooks: sanitize all rows before save; bind child events
  frappe.ui.form.on(PARENT_DT, {
    onload_post_render(frm) {
      ensureChildHandlers(frm);
      // attach masks for already-open row forms, if any
      const tableFn = resolveChildTableField(frm);
      const rows = tableFn ? (frm.doc[tableFn] || []) : [];
      rows.forEach(r => tryBindMask(frm, r.doctype, r.name));
    },
    refresh(frm) {
      ensureChildHandlers(frm);
    },
    validate(frm) {
      const tableFn = resolveChildTableField(frm);
      const rows = tableFn ? (frm.doc[tableFn] || []) : [];
      rows.forEach(r => coerceChildRow(r.doctype, r.name));
      if (tableFn) frm.refresh_field(tableFn);
    }
  });
})();

// Client Script | DocType: SRV_POST
(() => {
  const CHILD_TABLE = "table_kyqc";      // child table field on SRV_POST
  const CHILD_DTYPE = "SRV POST RE";     // child row DocType

  // exact child fieldnames (read-only in UI is fine)
  const PART_FN = "srv_part_no";
  const RECV_FN = "recieved_quantity";   // note the spelling in your schema

  function getGrid(frm) {
    return frm.get_field(CHILD_TABLE)?.grid;
  }

  // return the single selected base row doc, else null
  function getSingleSelected(grid) {
    if (!grid) return null;
    if (typeof grid.get_selected_children === "function") {
      const rows = grid.get_selected_children();
      return rows && rows.length === 1 ? rows[0] : null;
    }
    const idxs = grid.get_selected?.() || [];
    return (idxs.length === 1) ? grid.grid_rows[idxs[0]]?.doc : null;
  }

  // copy ONLY srv_part_no and recieved_quantity into the new row
  function copyCoreFields(newDoc, baseDoc) {
    frappe.model.set_value(newDoc.doctype, newDoc.name, PART_FN, baseDoc[PART_FN] || null);
    frappe.model.set_value(newDoc.doctype, newDoc.name, RECV_FN, baseDoc[RECV_FN] || 0);
  }

  // Hook the standard "+ Add Row" to prefill from the single checked row
  function hookAddRow(frm) {
    const grid = getGrid(frm);
    if (!grid || grid.__prefillHooked) return;
    grid.__prefillHooked = true;

    const origAdd = grid.add_new_row?.bind(grid);

    grid.add_new_row = function (...args) {
      const base = getSingleSelected(this);

      // create the row first (standard behavior)
      const before = this.grid_rows.length;
      const ret = origAdd ? origAdd(...args) : undefined;
      const after = this.grid_rows.length;

      // if a row was added and exactly one base row is selected, prefill it
      if (base && after > before) {
        const newRow = this.grid_rows[after - 1]?.doc;
        if (newRow) copyCoreFields(newRow, base);
      }

      frm.refresh_field(CHILD_TABLE);
      return ret;
    };
  }

  // (optional) make these two fields read-only inside the expanded row form
  function lockReadonlyInRowForm(frm) {
    const grid = getGrid(frm);
    if (!grid || grid.__lockOnce) return;
    grid.__lockOnce = true;

    const prev = grid.on_form_render;
    grid.on_form_render = function (gr) {
      if (typeof prev === "function") prev(gr);
      const ff = gr?.grid_form?.fields_dict;
      ff?.[PART_FN]?.set_read_only?.(1);
      ff?.[RECV_FN]?.set_read_only?.(1);
    };
  }

  frappe.ui.form.on("SRV_POST", {
    onload_post_render(frm) { hookAddRow(frm); lockReadonlyInRowForm(frm); },
    refresh(frm)            { hookAddRow(frm); lockReadonlyInRowForm(frm); }
  });
})();

// Client Script | DocType: SRV_POST
(() => {
  const PARENT_DT   = "SRV_POST";
  const CHILD_DT    = "SRV POST RE";
  const CHILD_TABLE = "table_kyqc";

  const FN = {
    part:   "srv_part_no",
    recv:   "recieved_quantity",
    posted: "posted_quantity"
  };

  // Cap strategy for a part that appears on multiple rows:
  // "first" = use the first non-zero received as the cap (recommended)
  // "min"   = use the minimum received among duplicates
  const CAP_STRATEGY = "first";

  // ---------- helpers ----------
  const toNum = (v) => {
    if (v == null) return 0;
    const n = parseFloat(String(v).replace(/,/g, "").trim());
    return Number.isFinite(n) ? n : 0;
  };

  const rows = (frm) => Array.isArray(frm.doc[CHILD_TABLE]) ? frm.doc[CHILD_TABLE] : [];
  const rowsByPart = (frm, part) =>
    rows(frm).filter(r => (r[FN.part] || "").trim() === (part || "").trim());

  function capReceivedForPart(frm, part) {
    const set = rowsByPart(frm, part);
    if (!set.length) return 0;

    if (CAP_STRATEGY === "first") {
      const ordered = [...set].sort((a, b) => (a.idx || 0) - (b.idx || 0));
      for (const r of ordered) {
        const v = toNum(r[FN.recv]);
        if (v > 0) return v;
      }
      return 0;
    } else {
      const vals = set.map(r => toNum(r[FN.recv])).filter(v => v > 0);
      return vals.length ? Math.min(...vals) : 0;
    }
  }

  const totalPostedForPart = (frm, part) =>
    rowsByPart(frm, part).reduce((a, r) => a + toNum(r[FN.posted]), 0);

  function leftoverForRow(frm, row) {
    const part = (row[FN.part] || "").trim();
    if (!part) return 0;

    const cap = capReceivedForPart(frm, part);
    const others = rowsByPart(frm, part)
      .filter(r => r.name !== row.name)
      .reduce((a, r) => a + toNum(r[FN.posted]), 0);

    return Math.max(0, cap - others);
  }

  function sanitizeAndClamp(frm, row) {
    row[FN.posted] = Math.max(0, toNum(row[FN.posted]));
    const part = (row[FN.part] || "").trim();
    if (!part) return;
    const cap = leftoverForRow(frm, row);
    if (row[FN.posted] > cap) {
      row[FN.posted] = cap;
      //frappe.show_alert({ message: __("{0}: capped to {1}", [part, cap]), indicator: "orange" });
    }
  }

  // ---------- UI helpers ----------
  function grid(frm) { return frm.get_field(CHILD_TABLE)?.grid; }

  // Ensure default add controls are available (in case another script hid them)
  function ensureCanAddRows(frm) {
    const g = grid(frm); if (!g) return;
    g.df.cannot_add_rows = false;
    g.cannot_add_rows    = false;
    const $w = $(g.wrapper);
    $w.find('.grid-add-row, .grid-add-multiple-rows, .grid-footer-help').show();
  }

  function addFromSelectedButton(frm) {
    const g = grid(frm);
    if (!g || g.__add_from_selected__) return;
    g.__add_from_selected__ = true;

    const handler = () => {
      const selected = typeof g.get_selected_children === "function"
        ? g.get_selected_children()
        : (g.get_selected?.() || []).map(i => g.grid_rows[i]?.doc).filter(Boolean);

      if (selected.length !== 1) {
        frappe.msgprint(__('Select exactly one row in the child table.'));
        return;
      }
      const base = selected[0];
      const part = (base[FN.part] || "").trim();
      if (!part) { frappe.msgprint(__('Selected row has no SRV Part No.')); return; }

      // Remaining for this part (using the cap rule)
      const cap  = capReceivedForPart(frm, part);
      const used = totalPostedForPart(frm, part);
      const left = Math.max(0, cap - used);
      if (left <= 0) {
        frappe.msgprint(__('No remaining quantity for this SRV Part No.'));
        return;
      }

      // Create the new row: copy same part and show same received qty (read-only in form)
      const r = frm.add_child(CHILD_TABLE);
      r[FN.part]   = part;
      r[FN.recv]   = base[FN.recv];      // display-only reference
      r[FN.posted] = left;               // user can lower this

      frm.refresh_field(CHILD_TABLE);

      // Open the new row so user can set Component Type etc.
      const gr = g.grid_rows_by_docname?.[r.name] || g.grid_rows.find(rr => rr.doc?.name === r.name);
      if (gr) gr.toggle_view(true);
    };

    // New grid API
    if (typeof g.add_custom_button === "function") {
      g.add_custom_button(__('Add From Selected'), handler);
    } else {
      // Fallback for older versions
      const $w = $(g.wrapper);
      const $slot = $(`<div style="margin:6px 0;"><button class="btn btn-sm btn-primary">${__("Add From Selected")}</button></div>`);
      $slot.find("button").on("click", handler);
      const $head = $w.find(".grid-heading-row,.grid-head-row").first();
      $head.length ? $head.after($slot) : $w.prepend($slot);
    }
  }

  // Make received qty & part no read-only in the inline form
  function lockReadonlyOnForm(frm) {
    const g = grid(frm); if (!g || g.__lock_readonly__) return;
    g.__lock_readonly__ = true;
    const prev = g.on_form_render;
    g.on_form_render = function (grid_row) {
      if (typeof prev === "function") prev(grid_row);
      const gf = grid_row?.grid_form?.fields_dict;
      gf?.[FN.part]?.set_read_only?.(1);
      gf?.[FN.recv]?.set_read_only?.(1);
      // numeric mask for posted
      const $inp = gf?.[FN.posted]?.$input;
      if ($inp && !$inp.__mask__) {
        $inp.__mask__ = true;
        $inp.on("input", () => {
          const v = $inp.val();
          const filtered = v.replace(/[^0-9.]/g, "").replace(/^([^.]*\.)|\./g, "$1");
          if (filtered !== v) $inp.val(filtered);
        });
      }
    };
  }

  // ---------- child events (clamp while typing) ----------
  frappe.ui.form.on(CHILD_DT, {
    [FN.posted](frm, cdt, cdn) {
      const row = locals[cdt][cdn]; if (!row) return;
      sanitizeAndClamp(frm, row);
      frm.refresh_field(CHILD_TABLE);
    },
    [FN.recv](frm, cdt, cdn) {
      const row = locals[cdt][cdn]; if (!row) return;
      const part = (row[FN.part] || "").trim();
      rowsByPart(frm, part).forEach(r => sanitizeAndClamp(frm, r));
      frm.refresh_field(CHILD_TABLE);
    }
  });

  // ---------- parent events ----------
  frappe.ui.form.on(PARENT_DT, {
    onload_post_render(frm) {
      ensureCanAddRows(frm);
      addFromSelectedButton(frm);
      lockReadonlyOnForm(frm);
    },
    refresh(frm) {
      ensureCanAddRows(frm);
      addFromSelectedButton(frm);
      lockReadonlyOnForm(frm);
    },
    validate(frm) {
      rows(frm).forEach(r => sanitizeAndClamp(frm, r));
      frm.refresh_field(CHILD_TABLE);

      const parts = [...new Set(rows(frm)
        .map(r => (r[FN.part] || "").trim())
        .filter(Boolean))];

      const bad = [];
      for (const p of parts) {
        const cap  = capReceivedForPart(frm, p);
        const used = totalPostedForPart(frm, p);
        if (used > cap) bad.push(`${p}: posted ${used} > received ${cap}`);
      }
      if (bad.length) {
        frappe.throw(__(
          "For these SRV Part No, Σ(Posted) must be ≤ Received (single base):<br>{0}",
          [bad.map(x => `• ${frappe.utils.escape_html(x)}`).join("<br>")]
        ));
      }
    }
  });
})();

