// ---------- Helpers ----------
function toNumOrNull(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (!s) return null;
  // allow digits only (your rule), but don't force to 0 when empty
  const cleaned = s.replace(/[^\d]/g, "");
  if (!cleaned) return null;
  const n = parseFloat(cleaned);
  return isNaN(n) ? null : n;
}

function digitsOnly(fieldname, cdt, cdn) {
  const d = locals[cdt][cdn] || {};
  const raw = (d[fieldname] ?? "").toString();
  const cleaned = raw.replace(/\D/g, ""); // keep only digits 0-9
  if (raw !== cleaned) {
    frappe.model.set_value(cdt, cdn, fieldname, cleaned);
  }
}

function getOrdField(d) {
  return d.hasOwnProperty("ordered_qty") ? "ordered_qty" : "odered_qty";
}

/**
 * Normalize one row so that:
 *   rec_qty ≤ ordered_qty
 *   ret_qty ≤ ordered_qty
 * Behavior:
 *   - If user edits rec/ret and it exceeds order, bump order up (nearest valid).
 *   - If user edits order and it's below max(rec,ret), bump order up.
 *   - If edited value is empty, do nothing (avoid forcing 0).
 */
function normalizeRow(cdt, cdn, changed_field) {
  const d = locals[cdt][cdn];
  if (!d) return;

  if (d.__normalizing__) return;        // re-entrancy guard
  d.__normalizing__ = true;

  const ordField = getOrdField(d);

  // current values (null if empty)
  let rec = toNumOrNull(d.rec_qty);
  let ord = toNumOrNull(d[ordField]);
  let ret = toNumOrNull(d.ret_qty);

  // If the just-edited field is empty, skip normalization entirely
  // so we don't coerce to 0 while the user is typing.
  if (changed_field === "rec_qty" && rec === null) { d.__normalizing__ = false; return; }
  if ((changed_field === "ordered_qty" || changed_field === "odered_qty") && ord === null) { d.__normalizing__ = false; return; }
  if (changed_field === "ret_qty" && ret === null) { d.__normalizing__ = false; return; }

  // Defaults: treat missing values as 0 only for comparison, but prefer bumping order up.
  const recN = rec ?? 0;
  const retN = ret ?? 0;
  let ordN = ord ?? 0;

  if (changed_field === "rec_qty") {
    if (recN > ordN) ordN = recN;                     // nearest valid: raise order
  } else if (changed_field === "ret_qty") {
    if (retN > ordN) ordN = retN;                     // nearest valid: raise order
  } else if (changed_field === "ordered_qty" || changed_field === "odered_qty") {
    const need = Math.max(recN, retN);
    if (ordN < need) ordN = need;                     // raise order to satisfy both
  }

  // Write back only if changed (no messages)
  if (ord !== ordN) frappe.model.set_value(cdt, cdn, ordField, ordN);

  // We don't clamp rec/ret down; we keep user's numbers and raise order to match,
  // which is the "nearby value" that preserves the entered quantities.

  d.__normalizing__ = false;
}

