  },
  ordered_qty(frm, cdt, cdn) {
    digitsOnly("ordered_qty", cdt, cdn);
    normalizeRow(cdt, cdn, "ordered_qty");
  },
  // fallback for mis-spelled schema
  odered_qty(frm, cdt, cdn) {
    digitsOnly("odered_qty", cdt, cdn);
    normalizeRow(cdt, cdn, "odered_qty");
  },
  ret_qty(frm, cdt, cdn) {
    digitsOnly("ret_qty", cdt, cdn);
    normalizeRow(cdt, cdn, "ret_qty");
  },
});

