function bind_inward_guard(frm){
  var df = frm.get_field("custom_enter_inward_number");
  if (!df || !df.$input) return;
  if (df.$input.data("bound_11digit")) return;
  df.$input.data("bound_11digit", 1);

  df.$input.attr("maxlength", 11);
  df.$input.on("input", function(){
    var v = df.$input.val() || "";
    v = v.replace(/\D+/g, "");
    if (v.length > 11) {
      v = v.slice(0,11);
      frappe.show_alert("Max 11 digits");
    }
    if (v !== (frm.doc.custom_enter_inward_number || "")) frm.set_value("custom_enter_inward_number", v);
  });
  df.$input.on("blur", function(){
    var v = df.$input.val() || "";
    if (v && v.length < 11) {
      frappe.msgprint('"Inward No" must be exactly 11 digits.');
    }
  });
}

function normalize_and_update(frm){
  var raw = frm.doc.custom_enter_inward_number || "";
  var digits = raw.replace(/\D+/g, "").slice(0,11);
  if (digits !== raw) { frm.set_value("custom_enter_inward_number", digits); return; }
  update_last5(frm);
}

function update_last5(frm){
  var v = frm.doc.custom_enter_inward_number || "";
  var last5 = v.length >= 5 ? v.slice(-5) : "";
  if (frm.doc.custom_srv_no !== last5) frm.set_value("custom_srv_no", last5);
}

