// Client Script | DocType: Purchase Receipt
(() => {
  const PARENT_DT   = "Purchase Receipt";
  const CHILD_DT    = "Purchase Receipt Item";
  const CHILD_TABLE = "items";

  const FN = {
    item:    "item_code",
    qty:     "qty",
    rate:    "rate",
    amount:  "amount"
  };

  // ---------- UI helpers ----------
  function grid(frm) { return frm.get_field(CHILD_TABLE)?.grid; }

  // Hide ERPNext’s built-in “Add Row” controls
  function hideDefaultAddRows(frm) {
    const g = grid(frm); if (!g) return;
    g.df.cannot_add_rows = true;
    g.cannot_add_rows    = true;
    const $w = $(g.wrapper);
    $w.find('.grid-add-row, .grid-add-multiple-rows, .grid-footer-help').hide();
  }

  // Add our custom "Add Data" button
  function addCustomAddButton(frm) {
    const g = grid(frm);
    if (!g || g.__custom_add__) return;
    g.__custom_add__ = true;

    const handler = () => {
      const r = frm.add_child(CHILD_TABLE);
      // defaults
      r[FN.qty]    = 1;
      r[FN.rate]   = 0;
      r[FN.amount] = 0;

      frm.refresh_field(CHILD_TABLE);

      // auto-open new row
      const gr = g.grid_rows_by_docname?.[r.name] || g.grid_rows.find(rr => rr.doc?.name === r.name);
      if (gr) gr.toggle_view(true);
    };

    if (typeof g.add_custom_button === "function") {
      g.add_custom_button(__('Add Data'), handler);
    } else {
      // fallback for older versions
      const $w = $(g.wrapper);
      const $slot = $(`<div style="margin:6px 0;"><button class="btn btn-sm btn-primary">${__("Add Data")}</button></div>`);
      $slot.find("button").on("click", handler);
      const $head = $w.find(".grid-heading-row,.grid-head-row").first();
      $head.length ? $head.after($slot) : $w.prepend($slot);
    }
  }

  // ---------- parent events ----------
  frappe.ui.form.on(PARENT_DT, {
    onload_post_render(frm) {
      hideDefaultAddRows(frm);
      addCustomAddButton(frm);
    },
    refresh(frm) {
      hideDefaultAddRows(frm);
      addCustomAddButton(frm);
    }
  });
})();

