// Helper function to build full path
function update_location_display(cdt, cdn) {
  let row = locals[cdt][cdn];
  let wh = row.s_warehouse || row.t_warehouse || "";
  let block = row.custom_block || "";
  let rack = row.custom_rack || "";

  let location_path = [wh, block, rack].filter(Boolean).join(" > ");
  frappe.model.set_value(cdt, cdn, "custom_location_display", location_path);
}

