frappe.ui.form.on('Stock Entry Detail', {
    custom_exp_date: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (row.custom_exp_date) {
            let exp_date = frappe.datetime.str_to_obj(row.custom_exp_date);
            let today = frappe.datetime.now_date();
            let five_years_later = frappe.datetime.add_years(today, 5);

            if (exp_date < today || exp_date > five_years_later) {
                frappe.model.set_value(cdt, cdn, 'custom_exp_date', '');
            }
        }
    }
});
